template.script:
document.addEventListener('DOMContentLoaded', function() {
    const addToCartBtn = document.getElementById('addToCartBtn');
    const simplePopup = document.getElementById('simplePopup');
    const closePopupBtn = simplePopup ? simplePopup.querySelector('.popup-close') : null;

    if (addToCartBtn && simplePopup) {

        // 1. Add to Cart click: Show Popup
        addToCartBtn.addEventListener('click', function(e) {
            e.preventDefault(); // Default cart action ko rokna zaroori hai

            // Popup ko display: block ya visible karna
            simplePopup.style.display = 'block';

            // Pop-up state ko default pe reset karo
            const genderSelection = document.getElementById('genderSelection');
            const giftForm = document.getElementById('giftForm');
            const buttonGroup = simplePopup.querySelector('.button-group');
            const questionParagraph = simplePopup.querySelector('p:not(#genderSelection p)'); // Question paragraph select karna

            if (genderSelection) genderSelection.style.display = 'none';
            if (giftForm) giftForm.style.display = 'none';

            // Question aur Yes/No buttons ko hide karo
            if (questionParagraph) questionParagraph.style.display = 'block';
            if (buttonGroup) buttonGroup.style.display = 'flex';
        });
    }

    // 2. Close Popup button handler
    if (closePopupBtn) {
        closePopupBtn.addEventListener('click', function() {
            simplePopup.style.display = 'none';
        });
    }

    // 3. Optional: Backdrop click par band karna
    if (simplePopup) {
        simplePopup.addEventListener('click', function(e) {
            if (e.target.id === 'simplePopup') {
                simplePopup.style.display = 'none';
            }
        });
    }
});
